--
-- Structure for view `work_order_extract_status`
--
DROP TABLE IF EXISTS `work_order_extract_status`;

CREATE VIEW `work_order_extract_status`  AS SELECT `wo`.`id` AS `id`, `wo`.`work_order_number` AS `work_order_number`, `wo`.`estimated_value` AS `estimated_value`, `wo`.`actual_value` AS `actual_value`, CASE WHEN `pewo`.`id` is not null THEN 1 ELSE 0 END AS `in_partial`, CASE WHEN `frewo`.`id` is not null THEN 1 ELSE 0 END AS `in_final_regular`, CASE WHEN `ffpewo`.`id` is not null THEN 1 ELSE 0 END AS `in_final_for_partial`, coalesce(sum(`pewo`.`extract_value`),0) AS `partial_total`, coalesce(sum(`frewo`.`extract_value`),0) AS `final_regular_total`, coalesce(sum(`ffpewo`.`extract_value`),0) AS `final_for_partial_total`, coalesce(sum(`pewo`.`extract_value`),0) + coalesce(sum(`frewo`.`extract_value`),0) + coalesce(sum(`ffpewo`.`extract_value`),0) AS `total_extracted` FROM (((`work_orders` `wo` left join `partial_extract_work_orders` `pewo` on(`wo`.`id` = `pewo`.`work_order_id`)) left join `final_regular_extract_work_orders` `frewo` on(`wo`.`id` = `frewo`.`work_order_id`)) left join `final_for_partial_extract_work_orders` `ffpewo` on(`wo`.`id` = `ffpewo`.`work_order_id`)) GROUP BY `wo`.`id` ;

